<?php
session_start();if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}require_once __DIR__.'/../config/db.php';if(!$pdo)die('Baza sozlanmagan.');
function ha($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='create_test'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');if($title!==''){$st=$pdo->prepare('INSERT INTO online_tests(title,description,is_active) VALUES(?,?,1)');$st->execute([$title,$desc]);}}
 if($action==='add_question'){$tid=(int)($_POST['test_id']??0);$question=trim($_POST['question_text']??'');$a=trim($_POST['option_a']??'');$b=trim($_POST['option_b']??'');$c=trim($_POST['option_c']??'');$d=trim($_POST['option_d']??'');$correct=$_POST['correct_option']??'';$check=$pdo->prepare('SELECT id FROM online_tests WHERE id=?');$check->execute([$tid]);if($check->fetch()&&$question!==''&&$a!==''&&$b!==''&&$c!==''&&$d!==''&&in_array($correct,['A','B','C','D'],true)){$st=$pdo->prepare('INSERT INTO test_questions(test_id,question_text,option_a,option_b,option_c,option_d,correct_option) VALUES(?,?,?,?,?,?,?)');$st->execute([$tid,$question,$a,$b,$c,$d,$correct]);}}
 if($action==='delete_question'){$pdo->prepare('DELETE FROM test_questions WHERE id=?')->execute([(int)$_POST['question_id']]);}
 if($action==='toggle_test'){$pdo->prepare('UPDATE online_tests SET is_active=IF(is_active=1,0,1) WHERE id=?')->execute([(int)$_POST['test_id']]);}
 header('Location: tests.php?saved=1');exit;
}
$tests=$pdo->query('SELECT t.*,COUNT(q.id) question_count FROM online_tests t LEFT JOIN test_questions q ON q.test_id=t.id GROUP BY t.id ORDER BY t.created_at DESC')->fetchAll();$selected=(int)($_GET['test_id']??($tests[0]['id']??0));$st=$pdo->prepare('SELECT * FROM test_questions WHERE test_id=? ORDER BY sort_order,id');$st->execute([$selected]);$questions=$st->fetchAll();
?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Testlar boshqaruvi</title><link rel="stylesheet" href="../assets/css/style.css?v=8"><style>.admin-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.panel-box{padding:22px;border:1px solid #342027;background:#121216;border-radius:16px}.panel-box label{display:block;margin:10px 0;color:#bbb;font-size:13px}.panel-box input,.panel-box textarea,.panel-box select{display:block;width:100%;padding:11px;background:#08080a;border:1px solid #393940;border-radius:8px;color:#fff;margin-top:5px}.question-row{padding:14px 0;border-bottom:1px solid #333}</style></head><body class="dashboard-body"><header class="site-header"><a class="brand" href="dashboard.php"><span class="brand-mark">A</span><span>ALGORITM<small>Administrator</small></span></a><nav><a href="dashboard.php">Panel</a><a href="courses.php">Kurslar</a><a href="payments.php">To‘lovlar</a><a href="test_results.php">Test natijalari</a><a class="nav-cta" href="logout.php">Chiqish</a></nav></header><main class="dashboard"><div class="dashboard-title"><div><span class="eyebrow">TA’LIM MODULI</span><h1>Testlar boshqaruvi</h1><p>Test, savollar, to‘rtta variant va to‘g‘ri javobni kiriting.</p></div><a class="button primary" href="../tests.php">Testlar sahifasi ↗</a></div><?php if(isset($_GET['saved'])):?><div class="alert success">O‘zgarish saqlandi.</div><?php endif;?><div class="admin-grid"><section class="panel-box"><h2>Yangi test yaratish</h2><form method="post"><input type="hidden" name="action" value="create_test"><label>Test nomi<input name="title" required maxlength="180"></label><label>Izoh<textarea name="description" rows="3"></textarea></label><button class="button primary" type="submit">Test yaratish</button></form></section><section class="panel-box"><h2>Savol qo‘shish</h2><form method="post"><input type="hidden" name="action" value="add_question"><label>Test<select name="test_id" required><?php foreach($tests as $t):?><option value="<?=$t['id']?>" <?=($selected===(int)$t['id']?'selected':'')?>><?=ha($t['title'])?></option><?php endforeach;?></select></label><label>Savol<textarea name="question_text" rows="2" required></textarea></label><?php foreach(['a'=>'A varianti','b'=>'B varianti','c'=>'C varianti','d'=>'D varianti'] as $k=>$label):?><label><?=$label?><input name="option_<?=$k?>" required maxlength="500"></label><?php endforeach;?><label>To‘g‘ri javob<select name="correct_option"><option>A</option><option>B</option><option>C</option><option>D</option></select></label><button class="button primary" type="submit">Savolni saqlash</button></form></section></div><section class="table-card" style="margin-top:20px"><div class="table-heading"><h2>Mavjud testlar</h2></div><div class="table-scroll"><table><thead><tr><th>Test</th><th>Savollar</th><th>Holat</th><th>Amallar</th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td><a href="?test_id=<?=$t['id']?>"><?=ha($t['title'])?></a></td><td><?=$t['question_count']?></td><td><?=$t['is_active']?'Faol':'Yashirilgan'?></td><td><form method="post"><input type="hidden" name="action" value="toggle_test"><input type="hidden" name="test_id" value="<?=$t['id']?>"><button class="button secondary" type="submit"><?=$t['is_active']?'Yashirish':'Faollashtirish'?></button></form></td></tr><?php endforeach;?><?php if(!$tests):?><tr><td colspan="4">Hali test yaratilmagan.</td></tr><?php endif;?></tbody></table></div></section><section class="table-card" style="margin-top:20px"><div class="table-heading"><h2><?=ha(($tests[array_search($selected,array_column($tests,'id'))]['title']??'Tanlangan test'))?> — savollar</h2></div><div style="padding:20px"><?php foreach($questions as $q):?><div class="question-row"><strong><?=ha($q['question_text'])?></strong><p>A. <?=ha($q['option_a'])?> · B. <?=ha($q['option_b'])?> · C. <?=ha($q['option_c'])?> · D. <?=ha($q['option_d'])?></p><small>To‘g‘ri javob: <?=ha($q['correct_option'])?></small><form method="post" style="display:inline-block;margin-left:12px"><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><button class="button secondary" type="submit" onclick="return confirm('Savol o‘chirilsinmi?')">O‘chirish</button></form></div><?php endforeach;?><?php if(!$questions):?><p>Bu testda savollar yo‘q.</p><?php endif;?></div></section></main><script src="../assets/js/theme.js?v=8"></script></body></html>
